#!/usr/bin/env bash
# Question 6: One worker takes no Pods. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

case "${Q6_FAULT}" in
  cordoned)
    kubectl -n "${Q6_NS}" scale deployment/spread --replicas=2
    sleep 15
    [[ "$(kubectl -n "${Q6_NS}" get deployment spread -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "spread still runs 2 replicas" >&2; exit 1; }
    ;;
  taint-noschedule)
    kubectl -n "${Q6_NS}" scale deployment/spread --replicas=2
    sleep 15
    [[ "$(kubectl -n "${Q6_NS}" get deployment spread -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "spread still runs 2 replicas" >&2; exit 1; }
    ;;
  taint-noexecute)
    kubectl -n "${Q6_NS}" scale deployment/spread --replicas=2
    sleep 15
    [[ "$(kubectl -n "${Q6_NS}" get deployment spread -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "spread still runs 2 replicas" >&2; exit 1; }
    ;;
  label-removed)
    kubectl -n "${Q6_NS}" scale deployment/spread --replicas=2
    sleep 15
    [[ "$(kubectl -n "${Q6_NS}" get deployment spread -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "spread still runs 2 replicas" >&2; exit 1; }
    ;;
  max-pods)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q6_NODE}" -o jsonpath='{.status.allocatable.pods}')" == 2 ]] && break
      sleep 2
    done
    [[ "$(kubectl get node "${Q6_NODE}" -o jsonpath='{.status.allocatable.pods}')" == 2 ]] || { echo "the kubelet did not take maxPods 2" >&2; exit 1; }
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q6_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" == True ]] && break
      sleep 2
    done
    kubectl -n "${Q6_NS}" scale deployment/spread --replicas=2
    sleep 15
    [[ "$(kubectl -n "${Q6_NS}" get deployment spread -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "spread still runs 2 replicas" >&2; exit 1; }
    ;;
esac
